<script setup lang="ts">
import { computed,onMounted } from'vue';import{storeToRefs}from'pinia';import{useRoute,useRouter}from'vue-router';import FinanceSubnav from'../components/FinanceSubnav.vue';import FinanceScenarioBar from'../components/FinanceScenarioBar.vue';import{useFinanceStore}from'../runtime/finance-store';import'./finance-views.css'
const store=useFinanceStore(),route=useRoute(),router=useRouter();const{accounts,loading,error,month,scenario,actor}=storeToRefs(store);const money=(v:number)=>`¥${(v/100).toLocaleString('zh-CN',{minimumFractionDigits:2})}`;const typeLabel={cash:'现金',bank:'银行账户',wechat:'微信',alipay:'支付宝'}as const;const total=computed(()=>accounts.value.reduce((s,r)=>({o:s.o+r.openingBalanceCents,i:s.i+r.periodIncomeCents,e:s.e+r.periodExpenseCents,c:s.c+r.closingBalanceCents}),{o:0,i:0,e:0,c:0}));async function change(v:string){await router.replace({query:{month:v}});await store.loadAccounts(v)}onMounted(()=>store.loadAccounts(String(route.query.month??'2026-08')))
</script>
<template><section class="finance-page"><header class="finance-header"><div><h1>账户收支汇总</h1><p>合计基于所选月份的完整账户结果，不是全局资金统计。</p></div><FinanceScenarioBar :scenario="scenario" :role="actor.role" @scenario="store.setScenario" @role="store.setRole"/></header><FinanceSubnav/><div class="finance-toolbar"><label>业务月份<input :value="month" type="month" max="2026-08" @change="change(($event.target as HTMLInputElement).value)"></label></div><div v-if="error" class="finance-state error">{{error}}</div><div v-else-if="loading" class="finance-state">正在加载汇总…</div><div v-else-if="!accounts.length" class="finance-state">暂无汇总数据</div><div v-else class="finance-table-wrap"><table class="finance-table"><thead><tr><th>账户名称</th><th>类型</th><th class="fin-money">期初</th><th class="fin-money">收入</th><th class="fin-money">支出</th><th class="fin-money">期末</th></tr></thead><tbody><tr v-for="row in accounts" :key="row.account.id"><td>{{row.account.name}}</td><td>{{typeLabel[row.account.type]}}</td><td class="fin-money">{{money(row.openingBalanceCents)}}</td><td class="fin-money fin-income">{{money(row.periodIncomeCents)}}</td><td class="fin-money fin-expense">{{money(row.periodExpenseCents)}}</td><td class="fin-money"><strong>{{money(row.closingBalanceCents)}}</strong></td></tr></tbody><tfoot><tr><th colspan="2">合计</th><th class="fin-money">{{money(total.o)}}</th><th class="fin-money fin-income">{{money(total.i)}}</th><th class="fin-money fin-expense">{{money(total.e)}}</th><th class="fin-money">{{money(total.c)}}</th></tr></tfoot></table></div></section></template>
